import { normalizeRanges } from './normalize-ranges.mjs';
export function subtractRanges(base, removed) {
  const result = normalizeRanges(base);
  return result.filter(pair => !removed.some(cut => cut[0] <= pair[0] && cut[1] >= pair[1]));
}

